import { test, expect } from '@playwright/test';

test.describe('Column Visibility Toggle', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display all columns by default', async ({ page }) => {
    const columns = await page.locator('table thead th').count();
    expect(columns).toBeGreaterThan(0);
  });

  test('should toggle column visibility from settings menu', async ({ page }) => {
    await page.getByRole('button', { name: /settings/i }).click();
    await page.getByLabel('Column A').uncheck();
    await page.getByRole('button', { name: /apply/i }).click();

    const columnA = await page.locator('table thead th:has-text("Column A")').count();
    expect(columnA).toBe(0);
  });
});
